import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"保健食品注册备案查询 · 认准蓝帽子","description":"保健食品真伪官方查询教程：市场监管总局特殊食品信息查询平台核对\\"蓝帽子\\"注册/备案号，防老人保健品骗局。","frontmatter":{"title":"保健食品注册备案查询 · 认准蓝帽子","issuer":"国家市场监督管理总局","source_tier":"一级来源","version":"—","published":"—","source_url":"http://ypzsx.gsxt.gov.cn/specialfood/#/food","status":"现行服务","tags":["官方查询","保健食品","蓝帽子","防坑"],"type":"查询页","reviewed":false,"description":"保健食品真伪官方查询教程：市场监管总局特殊食品信息查询平台核对\\"蓝帽子\\"注册/备案号，防老人保健品骗局。"},"headers":[],"relativePath":"query/health-food.md","filePath":"query/health-food.md"}'),d={name:"query/health-food.md"};function l(h,t,s,n,i,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="保健食品注册备案查询-·-认准蓝帽子" tabindex="-1">保健食品注册备案查询 · 认准蓝帽子 <a class="header-anchor" href="#保健食品注册备案查询-·-认准蓝帽子" aria-label="Permalink to &quot;保健食品注册备案查询 · 认准蓝帽子&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据官方平台公开信息整理，查询步骤请以平台实际页面为准；入口改版时以市场监管总局官网为准。</p></div><blockquote><p><strong>官方入口</strong>：市场监管总局<a href="http://ypzsx.gsxt.gov.cn/specialfood/#/food" target="_blank" rel="noreferrer">特殊食品信息查询平台</a>（保健食品注册与备案信息查询）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>合法保健食品包装上必有<strong>蓝帽子标志 + 批准文号</strong>（注册：&quot;国食健注 G/J + 4 位年代号 + 4 位顺序号&quot;；备案：&quot;国食健备 + 4 位年代号 + 4 位顺序号&quot;）。<strong>没有蓝帽子就不是保健食品</strong>——卖给老年人的&quot;神药&quot;绝大多数根本没有这张&quot;身份证&quot;。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开 <a href="http://ypzsx.gsxt.gov.cn/specialfood/#/food" target="_blank" rel="noreferrer">特殊食品信息查询平台</a></td></tr><tr><td>2</td><td>选&quot;保健食品&quot;注册或备案库，输入产品名称或批准文号</td></tr><tr><td>3</td><td>核对结果：<strong>产品名称、注册人/生产企业、保健功能、适宜人群</strong>与包装宣称是否一致</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>查到且信息一致</td><td>正规注册/备案保健食品（<a href="http://ypzsx.gsxt.gov.cn/specialfood/#/food" target="_blank" rel="noreferrer">查询平台</a>）</td></tr><tr><td>查不到</td><td>不是保健食品——按法规不得宣称保健功能</td></tr><tr><td>功能宣称超出注册范围（如&quot;治疗糖尿病&quot;）</td><td>违规宣传，保健食品<strong>不得宣称疾病治疗功能</strong></td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;这保健品能降压降糖替代吃药&quot;</td><td>保健食品不是药物，不能代替药物治疗疾病（蓝帽子产品也不允许如此宣称）</td></tr><tr><td>&quot;会销专场/免费旅游送保健品&quot;</td><td>先查蓝帽子文号，再查功能是否与宣称一致</td></tr><tr><td>【本站提示】给老人买之前替他查一次，30 秒可能省下几千块</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>药品：<a href="/SageRelay/query/drug.html">药品批准文号查询</a></li><li>化妆品：<a href="/SageRelay/query/cosmetics.html">化妆品备案/注册查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>市场监管总局特殊食品信息查询平台（一级来源）</td></tr><tr><td>入口</td><td><a href="http://ypzsx.gsxt.gov.cn/specialfood/#/food" target="_blank" rel="noreferrer">ypzsx.gsxt.gov.cn/specialfood</a>（入口以市场监管总局官网为准）</td></tr></tbody></table>',15)])])}const f=a(d,[["render",l]]);export{b as __pageData,f as default};
